import{_ as e,o as i,c as a,a3 as t}from"./chunks/framework.vDgOMd_y.js";const g=JSON.parse('{"title":"Sessions and context","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/sessions.md","filePath":"en/guides/sessions.md"}'),o={name:"en/guides/sessions.md"};function n(r,s,l,d,c,p){return i(),a("div",null,[...s[0]||(s[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/guides/sessions.md for this page in Markdown format</div><h1 id="sessions-and-context" tabindex="-1">Sessions and context <a class="header-anchor" href="#sessions-and-context" aria-label="Permalink to &quot;Sessions and context&quot;">​</a></h1><p>Kimi Code CLI persists every conversation as a &quot;session&quot; — storing message history and metadata so you can close the terminal and pick up right where you left off. This page covers how to resume sessions, manage context, and export or fork sessions.</p><h2 id="session-storage" tabindex="-1">Session storage <a class="header-anchor" href="#session-storage" aria-label="Permalink to &quot;Session storage&quot;">​</a></h2><p>All sessions are saved under <code>$KIMI_CODE_HOME/sessions/</code> (default: <code>~/.kimi-code/sessions/</code>), grouped by working directory:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.kimi-code/</span></span>
<span class="line"><span>├── config.toml</span></span>
<span class="line"><span>├── session_index.jsonl</span></span>
<span class="line"><span>└── sessions/</span></span>
<span class="line"><span>    └── &lt;workDirKey&gt;/</span></span>
<span class="line"><span>        └── &lt;sessionId&gt;/</span></span>
<span class="line"><span>            ├── state.json</span></span>
<span class="line"><span>            └── agents/</span></span>
<span class="line"><span>                ├── main/</span></span>
<span class="line"><span>                │   └── wire.jsonl</span></span>
<span class="line"><span>                └── &lt;subagentId&gt;/</span></span>
<span class="line"><span>                    └── wire.jsonl</span></span></code></pre></div><ul><li><code>state.json</code>: session metadata such as title and creation time.</li><li><code>agents/*/wire.jsonl</code>: the agent event stream, used for session recovery and replay. It also carries a request trace — the tool schemas, request parameters, and MCP tool listings sent to the model — for debugging.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not manually edit files inside the <code>sessions/</code> directory — doing so may prevent sessions from being restored correctly.</p></div><h2 id="starting-and-resuming-sessions" tabindex="-1">Starting and resuming sessions <a class="header-anchor" href="#starting-and-resuming-sessions" aria-label="Permalink to &quot;Starting and resuming sessions&quot;">​</a></h2><p>Every time you run <code>kimi</code> directly it creates a new session. To resume a previous session, use one of the following:</p><p><strong>Resume the most recent session in the current directory:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span></code></pre></div><p><strong>Resume a specific session by ID:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abc123</span></span></code></pre></div><p><strong>Interactively browse session history and choose one:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>--continue</code> and <code>--session</code> are mutually exclusive.</p></div><h2 id="switching-sessions-inside-the-tui" tabindex="-1">Switching sessions inside the TUI <a class="header-anchor" href="#switching-sessions-inside-the-tui" aria-label="Permalink to &quot;Switching sessions inside the TUI&quot;">​</a></h2><p>You can manage sessions without leaving the terminal. The following slash commands are available only when the agent is idle:</p><ul><li><strong><code>/new</code></strong> (alias <code>/clear</code>): switch to a new session, discarding the current context.</li><li><strong><code>/sessions</code></strong> (alias <code>/resume</code>): browse and resume a previous session.</li><li><strong><code>/fork</code></strong>: fork the current session (see below).</li><li><strong><code>/title &lt;text&gt;</code></strong> (alias <code>/rename</code>): set a session title for easier identification; without arguments, displays the current title.</li></ul><h2 id="context-compression" tabindex="-1">Context compression <a class="header-anchor" href="#context-compression" aria-label="Permalink to &quot;Context compression&quot;">​</a></h2><p>As a conversation grows, Kimi Code CLI automatically compresses the message history when the context approaches the window limit, freeing up token space. You can also trigger compression manually at any time:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact</span></span></code></pre></div><p>You can pass a hint to tell the model what to prioritize when compressing:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact Keep the discussion about database migrations</span></span></code></pre></div><h2 id="forking-a-session" tabindex="-1">Forking a session <a class="header-anchor" href="#forking-a-session" aria-label="Permalink to &quot;Forking a session&quot;">​</a></h2><p>To explore a new direction without disrupting the current conversation, use <code>/fork</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/fork</span></span></code></pre></div><p>Forking does not switch you away: you stay in the original session and the conversation continues untouched. The fork is an independent copy you can switch to at any time using <code>/sessions</code>. A saved <code>/goal</code> is not copied to the fork. Start a new goal there if you want autonomous goal work.</p><h2 id="exporting-a-session" tabindex="-1">Exporting a session <a class="header-anchor" href="#exporting-a-session" aria-label="Permalink to &quot;Exporting a session&quot;">​</a></h2><p>Use <code>kimi export</code> to package a session as a ZIP file — useful for sharing, archiving, or filing a bug report:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sessionI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Omitting <code>sessionId</code> exports the most recent session in the current directory (with an interactive confirmation prompt; add <code>-y</code> to skip). Use <code>-o</code> to specify an output path:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sessionI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/my-session.zip</span></span></code></pre></div><p>The export includes all files in the session directory, including diagnostic logs. The global diagnostic log (<code>~/.kimi-code/logs/kimi-code.log</code>) is also bundled by default; add <code>--no-include-global-log</code> to exclude it.</p><p>You can also export from inside the TUI without leaving the interactive session:</p><ul><li><strong><code>/export-debug-zip</code></strong>: produces the same debug ZIP as <code>kimi export</code>.</li><li><strong><code>/export-md</code></strong> (alias <code>/export</code>): exports the conversation as a human-readable Markdown file, suitable for sharing or archiving. Accepts an optional path argument; without one, it writes to <code>kimi-export-&lt;short-id&gt;-&lt;timestamp&gt;.md</code> in the current working directory.</li></ul><p>In the web UI, <code>/export</code> downloads the current session as a diagnostic ZIP. It includes the persisted session data, diagnostic logs, and a bounded metadata-only <code>logs/kimi-web.jsonl</code> record of key browser events. Prompt text, WebSocket payloads, and console arguments are not copied into this browser log. This web command differs from the TUI <code>/export</code> alias above.</p><p>The browser buffers the ZIP before saving it, so web exports are limited to 64 MiB. For a larger session, use <code>kimi export &lt;sessionId&gt;</code> or the TUI <code>/export-debug-zip</code> command.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Exported files may contain code, command output, and file paths that are sensitive. Review the content before sharing.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../configuration/data-locations.html">Data locations</a> — full directory layout for session files</li><li><a href="./../reference/kimi-command.html">kimi command reference</a> — complete parameter reference for <code>--continue</code>, <code>--session</code>, <code>export</code>, and other commands</li></ul>`,42)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
